trait Shape { fn area(&self) -> u32; }
struct Square(u32);
impl Shape for Square { fn area(&self) -> u32 { self.0 * self.0 } }
fn area(shape: &dyn Shape) -> u32 { shape.area() }
fn main() { assert_eq!(area(&Square(3)), 9); }
